WHERE n.audit_status = 1 AND n.status IN (0, 1)
AND n.status = #{status}
AND EXISTS (SELECT 1 FROM novel_tag nt WHERE nt.novel_id = n.novel_id AND nt.tag_id = #{tagId})

mapper.select:
SELECT n.novel_id, n.author_id, n.title, n.cover_url, n.description, n.status, n.audit_status, n.total_words, n.latest_chapter_id, c.title AS latest_chapter_title, u.nickname AS author_name, n.created_at, n.updated_at FROM novel n JOIN app_user u ON u.user_id = n.author_id LEFT JOIN chapter c ON c.chapter_id = n.latest_chapter_id AND c.status = 1 AND c.audit_status = 1
ORDER BY n.total_words DESC, n.updated_at DESC ORDER BY n.created_at DESC ORDER BY n.updated_at DESC
LIMIT #{pageSize} OFFSET #{offset}

SELECT n.novel_id, n.author_id, n.title, n.cover_url, n.description, n.status, n.audit_status, n.total_words, n.latest_chapter_id, c.title AS latest_chapter_title, u.nickname AS author_name, n.created_at, n.updated_at FROM novel n JOIN app_user u ON u.user_id = n.author_id LEFT JOIN chapter c ON c.chapter_id = n.latest_chapter_id AND c.status = 1 AND c.audit_status = 1 WHERE n.audit_status = 1 AND n.status IN (0, 1) AND n.title LIKE CONCAT(#{keyword}, '%')
AND EXISTS (SELECT 1 FROM novel_tag nt WHERE nt.novel_id = n.novel_id AND nt.tag_id = #{tagId})
ORDER BY n.updated_at DESC LIMIT #{pageSize} OFFSET #{offset}

SELECT COUNT(*)
FROM novel
WHERE author_id = #{authorId}
